function generalKnowledgeQuestion(difficulty, question, options, answer) {
  const normalizedDifficulty = generalKnowledgeClampDifficulty(difficulty);
  const normalizedOptions = Array.from(new Set(options.map(String)));
  const normalizedAnswer = String(answer);

  if (!String(question || "").trim()) {
    throw new Error("General knowledge question is missing question text.");
  }

  if (normalizedOptions.length !== 4 || !normalizedOptions.includes(normalizedAnswer)) {
    throw new Error(`General knowledge question must have exactly 4 unique options including the answer: ${question}`);
  }

  return {
    question: String(question),
    options: normalizedOptions,
    answer: normalizedAnswer,
    difficulty: normalizedDifficulty,
  };
}

